import React from 'react';

const Toolbar: React.FC = () => {
    return (
        <div style={{ display: 'flex', justifyContent: 'space-between', padding: '10px', backgroundColor: '#f0f0f0' }}>
            <button>Home</button>
            <button>About</button>
            <button>Contact</button>
        </div>
    );
};

export default Toolbar;
